CREATE VIEW [purchase].[SupplierOutstanding] AS SELECT s.SupplierId,s.SupplierCode,s.SupplierName,s.OpeningBalance+ISNULL(SUM(purchase.PurchaseOutstanding(i.PurchaseInvoiceId)),0)OutstandingAmount,MIN(CASE WHEN purchase.PurchaseOutstanding(i.PurchaseInvoiceId)>0 THEN i.DueDate END)OldestDueDate FROM purchase.Suppliers s LEFT JOIN purchase.PurchaseInvoices i ON i.SupplierId=s.SupplierId AND i.IsDeleted=0 AND i.Status NOT IN('DRAFT','CANCELLED') WHERE s.IsDeleted=0 GROUP BY s.SupplierId,s.SupplierCode,s.SupplierName,s.OpeningBalance;
